 * `baseEnd`, half-open) replaced by a run of `side`'s `lines`. An insertion
 * has `baseStart === baseEnd`; a deletion has an empty `lines` array.
 * Changes are returned in base order.
 */
export function computeChanges(base, side) {
  const n = base.length
  const m = side.length
  const width = m + 1
  const dp = new Uint32Array((n + 1) * width)
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      const here = i * width + j
      dp[here] = base[i] === side[j] ? dp[here + width + 1] + 1 : Math.max(dp[here + width], dp[here + 1])
    }
