      flush(i, j)
      i++
      j++
    } else {
      if (changeStart === null) changeStart = { i, j }
      if (dp[(i + 1) * width + j] >= dp[i * width + j + 1]) i++
      else j++
    }
  }
  if (changeStart === null && (i < n || j < m)) changeStart = { i, j }
  flush(n, m)

  return changes
}
