 * Combines the per-side diffs against the base into merge regions, and
 * resolves each region to stable lines, one side's lines, both sides'
 * agreeing lines, or a conflict.
 */

import { computeChanges } from './diff.js'

function arraysEqual(a, b) {
  return a.length === b.length && a.every((line, index) => line === b[index])
}

// Reconstructs one side's lines across a region from that side's own changes
// within it, filling the gaps between and around them with the matching base
// lines (identical on that side, since nothing of that side's changed there).
function sideLines(base, changes, regionStart, regionEnd) {
  if (changes.length === 0) return base.slice(regionStart, regionEnd)
  const result = []
  let cursor = regionStart
  for (const change of changes) {
    result.push(...base.slice(cursor, change.baseStart))
    result.push(...change.lines)
    cursor = change.baseEnd
  }
  result.push(...base.slice(cursor, regionEnd))
  return result
}

// Groups the changes from both sides into regions: runs of overlapping
// change spans, absorbing any change that starts at or before the region's
// current end.
function computeMergedRegions(mineChanges, theirsChanges) {
  const tagged = [
    ...mineChanges.map(change => ({ side: 'mine', ...change })),
    ...theirsChanges.map(change => ({ side: 'theirs', ...change })),
  ].sort((a, b) => a.baseStart - b.baseStart)

  const regions = []
  let index = 0
  while (index < tagged.length) {
    let baseStart = tagged[index].baseStart
    let baseEnd = tagged[index].baseEnd
    const members = [tagged[index]]
    index++
    while (index < tagged.length && tagged[index].baseStart <= baseEnd) {
      baseEnd = Math.max(baseEnd, tagged[index].baseEnd)
      members.push(tagged[index])
      index++
    }
    regions.push({ baseStart, baseEnd, members })
  }
  return regions
}

// Resolves one region touched by at least one side's changes, following the
// mine/theirs/base equality rules, or reports it as a conflict.
function resolveRegion(base, region) {
  const { baseStart, baseEnd, members } = region
  const mineChanges = members.filter(member => member.side === 'mine')
  const theirsChanges = members.filter(member => member.side === 'theirs')
  const mineTouched = mineChanges.length > 0
  const theirsTouched = theirsChanges.length > 0

  const mineLines = sideLines(base, mineChanges, baseStart, baseEnd)
  const theirsLines = sideLines(base, theirsChanges, baseStart, baseEnd)
  const baseLines = base.slice(baseStart, baseEnd)

  if (mineTouched && !theirsTouched) return { kind: 'mine', lines: mineLines }
  if (theirsTouched && !mineTouched) return { kind: 'theirs', lines: theirsLines }

  if (arraysEqual(mineLines, theirsLines)) return { kind: 'both', lines: mineLines }
  if (arraysEqual(mineLines, baseLines)) return { kind: 'theirs', lines: theirsLines }
  if (arraysEqual(theirsLines, baseLines)) return { kind: 'mine', lines: mineLines }
  return { kind: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines }
}

/**
 * Runs the three-way merge of `mine` and `theirs` against `base`, returning
 * an ordered list of segments covering every base line exactly once: stable
 * segments (`{ kind: 'stable', lines }`) for base lines no change touches,
 * and resolved regions (`{ kind: 'mine' | 'theirs' | 'both', lines }` or
 * `{ kind: 'conflict', mine, base, theirs }`) for the rest.
 */
export function threeWayMerge(mine, base, theirs) {
