 * report the three-way merge of the second into the first and the third.
 */

import { readFileSync } from 'node:fs'
import { threeWayMerge } from './merge.js'
import { formatMerge, formatRegions } from './format.js'

const MODES = ['merge', 'merge2', 'regions']

function fail(message) {
  process.stderr.write(`${message}\n`)
  process.exit(2)
}

function splitDocuments(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const documents = [[]]
  for (const line of lines) {
    if (line === '%%%') documents.push([])
    else documents[documents.length - 1].push(line)
  }
  return documents
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !MODES.includes(args[0])) fail('error: usage: cli.js merge|merge2|regions')
  const mode = args[0]

  const documents = splitDocuments(readFileSync(0, 'utf8'))
  if (documents.length !== 3) fail('error: expected three parts separated by %%%')
  const [mine, base, theirs] = documents

  const segments = threeWayMerge(mine, base, theirs)
  const hasConflict = segments.some(segment => segment.kind === 'conflict')

  const output =
    mode === 'regions' ? formatRegions(segments) : formatMerge(segments, { includeBase: mode === 'merge' })
  process.stdout.write(output)
  process.exit(hasConflict ? 1 : 0)
}

main()
"}

